import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Dnb1kVW5.js";const p=JSON.parse('{"title":"Privacy","description":"","frontmatter":{"title":"Privacy"},"headers":[],"relativePath":"docs/concepts/privacy.md","filePath":"docs/concepts/privacy.md","lastUpdated":1789194236000}'),n={name:"docs/concepts/privacy.md"};function r(d,e,i,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Orby is built local-first: a model running on your own machine can handle chat, categorization, and every analysis in the app, and none of your data has to leave your device unless you explicitly connect a cloud model.</p><h2 id="account-number-masking" tabindex="-1">Account number masking <a class="header-anchor" href="#account-number-masking" aria-label="Permalink to &quot;Account number masking&quot;">​</a></h2><p>For financial statements, Orby intentionally redacts account numbers on ingest, and only ever stores the last 4 digits in its data stores. However, names, addresses, dates, and other potentially identifying information on transactions are saved, as otherwise you&#39;d lose a lot of useful information that your analyses rely upon.</p><p>For general documents, Orby does not redact any information on ingest.</p><h2 id="trusted-vs-untrusted-models" tabindex="-1">Trusted vs. untrusted models <a class="header-anchor" href="#trusted-vs-untrusted-models" aria-label="Permalink to &quot;Trusted vs. untrusted models&quot;">​</a></h2><p>In Settings, you can configure a <strong>trusted</strong> main model — the one that has access to your actual project data — separately from any <strong>untrusted supporting models</strong> used for other backend tasks. Chats always use the trusted model.</p><p>In some cases, like adding support new for statement extractors or statement downloaders, a powerful <strong>untrusted</strong> models needs access to your statement or webpage view - in these cases, the flows direct you to redact all your PII before sending any data to the untrusted model.</p><h2 id="redacting-documents-yourself" tabindex="-1">Redacting documents yourself <a class="header-anchor" href="#redacting-documents-yourself" aria-label="Permalink to &quot;Redacting documents yourself&quot;">​</a></h2><p>If you want to share or save a document (like a sample statement) without exposing personal information, use the standalone <a href="/orby-releases/docs/tools/pii-redactor">PII Redactor</a> tool directly.</p>',10)])])}const y=t(n,[["render",r]]);export{p as __pageData,y as default};
